{
  "rules": [
    "When sentiment is positive (≥0.2) in recent history, model tends to under-forecast; adjust forecast upward by 1-2% of recent mean.",
    "Model consistently under-estimates true price spikes; apply a 10-20% upward correction to forecast after a price surge >10% from prior 5-day average.",
    "Model exhibits strong mean reversion bias: if forecast is below 80, it often overshoots; cap forecast at 85 if recent 5-day average >85.",
    "After a sharp price drop (e.g., >5% from prior 5-day avg), model under-reacts; add 0.5-1.5% to forecast to capture sentiment-driven rebound.",
    "Model fails to capture sentiment-driven momentum in late horizon (last 5-7 days); for 30-day forecast, weight last 7 days’ sentiment 3x more than prior 11 days."
  ]
}
